Program 3: To demonstrate InputMismatchException


            Java

    // Java program to illustrate the
// nextLong() method of Scanner class in Java
// InputMismatchException

import java.util.*;

public class GFG1 {
    public static void main(String[] argv)
        throws Exception
    {

        try {

            String s = "Gfg 9 + 6 = 12.0";

            // create a new scanner
            // with the specified String Object
            Scanner scanner = new Scanner(s);

            while (scanner.hasNext()) {

                // if the next is a Long,
                // print found and the Long
                // since the value 60 is out of range
                // it throws an exception

                System.out.println("Next Long value :"
                                   + scanner.nextLong());
            }
            scanner.close();
        }
        catch (Exception e) {
            System.out.println("Exception thrown: " + e);
        }
    }
}



Output:
Exception thrown: java.util.InputMismatchException





Program 4: To demonstrate NoSuchElementException


            Java

    // Java program to illustrate the
// nextLong() method of Scanner class in Java
// NoSuchElementException

import java.util.*;

public class GFG1 {
    public static void main(String[] argv)
        throws Exception
    {

        try {

            String s = "Gfg";

            // create a new scanner
            // with the specified String Object
            Scanner scanner = new Scanner(s);

            // Trying to get the next Long value
            // more times than the scanner
            // Hence it will throw exception
            for (int i = 0; i < 5; i++) {

                // if the next is a Long,
                // print found and the Long
                if (scanner.hasNextLong()) {
                    System.out.println("Found Long value :"
                                       + scanner.nextLong());
                }

                // if no Long is found,
                // print "Not Found:" and the token
                else {
                    System.out.println("Not found Long value :"
                                       + scanner.next());
                }
            }
            scanner.close();
        }
        catch (Exception e) {
            System.out.println("Exception thrown: " + e);
        }
    }
}



Output:
Not found Long value :Gfg
Exception thrown: java.util.NoSuchElementException





Program 5: To demonstrate IllegalStateException


            Java

    // Java program to illustrate the
// nextLong() method of Scanner class in Java
// IllegalStateException

import java.util.*;

public class GFG1 {
    public static void main(String[] argv)
        throws Exception
    {

        try {

            String s = "Gfg 9 + 6 = 12.0";

            // create a new scanner
            // with the specified String Object
            Scanner scanner = new Scanner(s);

            // close the scanner
            scanner.close();
            System.out.println("Scanner Closed");

            System.out.println("Trying to get "
                               + "next Long value");

            while (scanner.hasNext()) {

                // if the next is a Long,
                // print found and the Long
                if (scanner.hasNextLong()) {
                    System.out.println("Found Long value :"
                                       + scanner.nextLong());
                }

                // if no Long is found,
                // print "Not Found:" and the token
                else {
                    System.out.println("Not found Long value :"
                                       + scanner.next());
                }
            }
        }
        catch (Exception e) {
            System.out.println("Exception thrown: " + e);
        }
    }
}



Output:
Scanner Closed
Trying to get next Long value
Exception thrown: java.lang.IllegalStateException: Scanner closed



